{
  "PROP-legion-backe-inv-017": {
    "property_id": "PROP-legion-backe-inv-017",
    "audit_result": {
      "property_id": "PROP-legion-backe-inv-017",
      "classification": "vulnerability",
      "code_path": "src/sales/LegionAbstractSale.sol::withdrawInvestedCapitalIfCanceled::L445-472",
      "proof_trace": "Both `withdrawInvestedCapitalIfCanceled()` (L445) and `withdrawExcessInvestedCapital()` (L316) carry an unconditional `whenNotPaused` modifier, and `pause()` is callable by Legion alone with no preconditions or time-lock. When the contract is paused, investors have zero self-help remedy to recover funds \u2014 `emergencyWithdraw` is `onlyLegion` and directs funds to a Legion-chosen receiver, not investors.",
      "attack_scenario": "Legion calls `cancel()` to cancel the sale, then immediately calls `pause()`; all subsequent investor calls to `withdrawInvestedCapitalIfCanceled()` revert with `EnforcedPause`, permanently freezing investor capital until Legion voluntarily unpauses.",
      "checklist_id": "PROP-legion-backe-inv-017"
    },
    "text": "Pause must preserve investor withdrawal access (refund, excess, cancel-withdraw).",
    "assertion": "paused == true => withdrawExcess() && withdrawIfCanceled() still callable",
    "covers": "SG-016",
    "severity": "HIGH",
    "type": "invariant"
  }
}

